SELECT 602 f,n.profile profile,CASE WHEN n.published_at IS NULL THEN 'null' WHEN (n.published_at+ifnull(n.published_offset,0)*60)/86400>=20714 THEN 'after' WHEN (n.published_at+ifnull(n.published_offset,0)*60)/86400>=20713 THEN 'in' WHEN (n.published_at+ifnull(n.published_offset,0)*60)/86400=20712 THEN 'b001' WHEN (n.published_at+ifnull(n.published_offset,0)*60)/86400>20683 THEN 'b002' WHEN (n.published_at+ifnull(n.published_offset,0)*60)/86400>20533 THEN 'b030' WHEN (n.published_at+ifnull(n.published_offset,0)*60)/86400>20348 THEN 'b180' ELSE 'b365' END pb,CASE WHEN n.dispatched_at IS NULL THEN 'none' WHEN (n.dispatched_at+ifnull(n.dispatched_offset,0)*60)/86400>=20714 THEN 'after' WHEN (n.dispatched_at+ifnull(n.dispatched_offset,0)*60)/86400>=20713 THEN 'in' ELSE 'before' END db,count(*) n,sum((n.dispatched_at+ifnull(n.dispatched_offset,0)*60)/86400>(n.published_at+ifnull(n.published_offset,0)*60)/86400) inv,sum((n.published_at+ifnull(n.published_offset,0)*60)/86400>20714) fut,sum(n.published_offset IS NULL) nooff,sum(n.published_has_time=1) timed,min((n.published_at+ifnull(n.published_offset,0)*60)/86400) min_pcd,min(n.id) min_id,max(n.id) max_id,min(n.ingested_at) min_ing,max(n.ingested_at) max_ing FROM notices n WHERE n.fetch_id=602 GROUP BY +n.profile,pb,db
